#nullable enable // autogenerated

using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Entities
{

    [AutoBuffDefinition(VanillaBuffNames.Entity.galeLeafArtifactPickup)]
    public class GaleLeafArtifactPickupBuff : BuffDefinition
    {
        public GaleLeafArtifactPickupBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new FloatModifier(EngineEntityProps.FRICTION, NumberOperator.Set, 0.15f));
            AddModifier(new FloatModifier(EngineEntityProps.GRAVITY, NumberOperator.Multiply, 0.1f));
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var entity = buff.GetEntity();
            if (entity != null)
            {
                var sign = Mathf.Sign(entity.Velocity.x);
                var value = Mathf.Max(Mathf.Abs(entity.Velocity.x) - 1, 0);
                entity.RenderRotation = Vector3.back * 3 * Mathf.Pow(sign * value, 3);
            }
        }
    }
}
